update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p011","body":"زندان یوسف نہ سہی وقت کی دسترس میں ہے\nمیں بس اتنا جانتا ہوں کہ ہر آدمی قفس میں ہے\n\nہزار سوچوں کی ایک شب اور ایک طرح کا دن\nجو کسی کے بس نہیں وہ کب اپنے بس میں ہے\n\nخواب بھی سارے دفن کیے زیرِ بحر\nعجب آئینہ داری اس کے عکس میں ہے\n\nکون ہے احمد ایسا جسے غمِ دنیا نہیں\nیہ بےچارگی یہ بےبسی نفس نفس میں ہے"},{"slug":"tum-p012","body":"چاند کی ٹھنڈی چاندنی\nجب بیچ صحن پہ آتی ہے\nتب کسی نام کی شمع\nلوگ اکثر جلایا کرتے ہیں\nکچھ درد سلگنے لگتے ہیں\nکچھ خواب سجایا کرتے ہیں\nوہ خواب جن کی حقیقت نہیں\nوہ شمع جو اجالا نہ کرے\nوہ درد جس کی دوا نہ ہو\nوہ دل جو دھڑکا نہ کرے\nوہ سفر جس کی منزل نہیں\nوہ زندگی جو حاصل نہیں\nاس جستجو میں کوئی بےسبب\nہر پل اپنا گھاٹا کیوں کرے\nیہ حماقتیں کوئی کیوں کرے\nکہ اندر ہی اندر مرتا رہے\nیہ کِیا دھرتا سب جس کا ہے\nاگر عشق ہے ! سو کرتا رہے"},{"slug":"tum-p013","body":"میں کون ہوں ، میں کیا ہوں\nمیں کون تھا ، میں کیا ہوا\n\nمجھے اپنی ہی جیسے کھوج رہی\nمیں خود ہی خود میں فنا ہوا\n\nمیری میں مجھ سے چھن گئی\nمیں خاک تھا ہوا ہوا\n\nمیں جاگتا رہا رات بھر\nاور دن بھر لا پتا ہوا\n\nنہ دعا ہوا ، نہ دغا ہوا\nنہ سکوں ہوا ، نہ سزا ہوا\n\nنہ کسی کی مجھے یاد آئی\nنہ کسی کی میں سدا ہوا\n\nمیرے بخت سب چلے گئے\nمیرا ہر خوف سچا ہوا\n\nجسے لگا کہ اس کا کوئی نہیں\nاحمد  اسی کا ہی تو خدا ہوا"},{"slug":"tum-p014","body":"تم! تم خواب، عتاب ، شباب۔ دل کی وہ کیفیت ہو جو دل تک ہی محدود رہ جانے والی ہے۔ تم! تم میرے فن سے بالاتر ہو شاید کیونکہ آج تک میں تمہیں ایک تحریر، ایک محفل اور ایک رمز میں نہیں کہہ سکا۔\nتم! تم ایک حقیقت ہو جسے میں خواب کر بیٹھا ہوں۔ تم! تم ایک رات ہو جس کی ٹھنڈک سے مجھے روشنیوں کی کرنیں جلانے لگ گئی ہیں۔ تم! تم وہ خیال ہو جو اکثر فراغت میں مجھے مصروف رکھتا ہے اور تم ہی میری لاشعوری بھی ہو کیونکہ جب میں تمہیں سوچتا ہوں تو کچھ اور نہیں سوجھتا ۔ تم! تم وہ راستہ ہو جہاں موجود تو کئی مسافر ہیں پر شاید جو کسی کی منزل کا معین نہیں۔ تم وہ چراغ ہو جو رات بھر جلتا رہتا ہے پر دن ہوتے ہی بےمقصد ہو جاتا ہے۔ تم! تم سمندر کی لہر ہو جو دل کے ساحل پہ آ کٹتی ہے۔ تم! تم بادل ہو جو جذبوں کی سرحد پہ برسنے لگتا ہے کہ ہوا اسے اپنے ساتھ اڑا لے جاتی ہے۔ تم! تم قافلہ ہو جس کی بھیڑ میں یہ دل پرامن رہتا ہے۔ تم! اس طرح کی سیکڑوں تمسیلیں ہو جسے میں اپنے ہاتھوں سے لکھتا ہوں۔\nسنو ! تم، تم ہو جاناں۔\nتم ان کہی ہو، ان سنی ہو ، غمی ہو، خوشی ہو، تھوڑی سہی ہو، ذرا نہیں ہو، آوارگی ہو، بےچارگی ہو، آشنگی ہو، تشنگی ہو، بےصبر ہو، بےخبر ہو، بےقدر ہو، بےاثر ہو، خوبرو ہو، روبرو ہو، جستجو ہو، آرزو ہو، پرکشش ہو ، چپ خلش ہو، ان کہی ہو، ان سنی ہو، روشنی ہو، زندگی ہو۔\nتم زندگی ہو۔"},{"slug":"tum-p015","body":"ستارے! چمکتے پتھر۔ کچھ آسمانوں پہ ملتے ہیں تو کچھ زمیں پہ۔ کچھ گھنی راتوں کو دکھتے ہیں تو کچھ کبھی نظر نہیں آتے۔ کچھ کو دوری مدحم کرتی جاتی ہے تو کچھ نظر میں ہی تب آتے ہیں جب دور جاتے ہیں۔ کچھ اپنی میعاد سے تجاوز نہیں کر پاتے تو کچھ معیار سے بڑھ  کر رونما ہوتے ہیں۔\nکچھ پہلے سے ہی مدحم سے دکھتے ہیں تو کچھ ابھر ابھر کر اپنی چمکاہٹ سے اپنے ہونے کا پتہ دیتے ہیں۔ چمکدار ستارے تو چاہے زینتِ فلک ہوں یا غرورِ زمیں۔ اکثریت انھی کی دلدادہ ہوتی ہے۔\nمیں سمجھتا ہوں کہ اصل فن تو مدحم ستاروں میں روشنی تلاش کرنا ہے کیونکہ ان کی تلاش صحیح موقع پہ نہ کی جائے تو یہ ہمیشہ کے لیے اوجھل ہو جاتے ہیں اور اپنا نشان ہی مٹا دیتے ہیں۔\nکچھ ستارے دور ہوتے ہیں تو کچھ آنکھوں کی تاک میں۔ کچھ ستاروں کی دوری سائنس فلاں فلاں روشنی کے سال بتاتی ہے تو کچھ چند فٹ کے فاصلے کے باوجود ہمیشہ کی مسافت رکھتے ہیں۔\nاک بات تو مشترک ہے آسمانی و زمینی ستاروں میں۔ دونوں ہی کسی موڑ پہ ٹوٹ جاتے ہیں۔ آسمانی ستاروں کو کسی سیارے کی کشش سکل اپنی جانب کھینچ لیتی ہے پر سوال یہ ہے کہ یہ زمینی ستارے آخر ٹوٹ کر کہاں جاتے ہیں؟"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
